import{_ as t,o as a,c as s,aa as o}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/en/diary/en_siotech_nastaveni.jpg",i="/buildary-help-preview/media/en/diary/en_siotech_teploty.jpg",n="/buildary-help-preview/media/cs/diary/siotech2.png",y=JSON.parse('{"title":"Digital Sensors","description":"","frontmatter":{"title":"Digital Sensors","wiki":"en:diary:sensors"},"headers":[],"relativePath":"en/diary/sensors.md","filePath":"en/diary/sensors.md","lastUpdated":1794388980000}'),l={name:"en/diary/sensors.md"};function d(c,e,p,h,u,m){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="digital-sensors" tabindex="-1">Digital Sensors <a class="header-anchor" href="#digital-sensors" aria-label="Permalink to &quot;Digital Sensors&quot;">​</a></h1><p>Buildary supports integration with autonomous digital sensors and measuring devices. The condition is that the measured data must be stored in a way that is accessible via the Internet and that the administrator of this data grants our application access, preferably through a web service that provides us with the required information.</p><p>If you have suggestions for devices that you would like us to integrate, please contact us.</p><h2 id="siotech-temperature-sensor" tabindex="-1">Siotech Temperature Sensor <a class="header-anchor" href="#siotech-temperature-sensor" aria-label="Permalink to &quot;Siotech Temperature Sensor&quot;">​</a></h2><figure class="shot" style="--w:610px;"><img src="'+r+'" alt="" width="400" loading="lazy"></figure><p>For those who want completely objective and accurate information about the temperature on the project, it is possible to connect an autonomous digital sensor. The Siotech sensor can be placed anywhere on the construction site, and it will send information about the current temperature at ten-minute intervals. The Siotech server will therefore contain a complete record of temperature changes throughout the monitored period, both numerically and graphically.</p><p>Buildary only imports data from the server for predefined times, so the user&#39;s workflow does not change at all.</p><p>Only the temperature is imported from the sensor, and it cannot then be manually edited in the diary.</p><p>The note will indicate that the temperature was imported from the sensor, together with its ID and the time of the measurement used.</p><p>To activate the sensor, simply enter your sensor ID in the <strong>Weather</strong> section of the diary settings.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you are interested in trying out the sensor, please contact us.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you enable temperature readings from the sensor, it is not possible to enter temperature data in advance. Data can only be imported retrospectively.</p></div><img src="'+i+'" alt="" width="400" loading="lazy"><img src="'+n+'" alt="" width="400" loading="lazy">',14)])])}const f=t(l,[["render",d]]);export{y as __pageData,f as default};
